pub fn totalPreviewTools() usize { return 20 * 40; }

test "tools dispatch hits shard previews not stub" {
    const gpa = std.testing.allocator;
    const out = try executePreview(gpa, "read_0_0", "{\"path\":\"a.txt\"}");
    try std.testing.expect(out != null);
    defer gpa.free(out.?);
    try std.testing.expect(std.mem.indexOf(u8, out.?, "preview:read_0_0") != null);
    const out2 = try executePreview(gpa, "bash_19_3", "{\"path\":\"x\"}");
    try std.testing.expect(out2 != null);
    defer gpa.free(out2.?);
    try std.testing.expect(std.mem.indexOf(u8, out2.?, "preview:bash_19_3") != null);
}
